ALTER TABLE "business_payments" ADD CONSTRAINT "business_payments_order_matches_direction" CHECK (("business_payments"."direction" = 'customer_receipt' and "business_payments"."sales_order_id" is not null and "business_payments"."purchase_order_id" is null and "business_payments"."import_expense_id" is null) or ("business_payments"."direction" = 'supplier_payment' and "business_payments"."sales_order_id" is null and (( "business_payments"."purchase_order_id" is not null and "business_payments"."import_expense_id" is null) or ("business_payments"."purchase_order_id" is null and "business_payments"."import_expense_id" is not null))));